class Solution {
    public int minOperations(int[] nums, int x) {
        int n = nums.length;
        int minOps = Integer.MAX_VALUE;
        for (int i = 0; i <= n; i++) {
            int leftSum = 0;
            for (int k = 0; k < i; k++) leftSum += nums[k];
            if (leftSum > x) break;
            for (int j = 0; j <= n - i; j++) {
                int rightSum = 0;
                for (int k = 0; k < j; k++) rightSum += nums[n - 1 - k];
                if (leftSum + rightSum == x) {
                    minOps = Math.min(minOps, i + j);
                }
            }
        }
        return minOps == Integer.MAX_VALUE ? -1 : minOps;
    }
}

